pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(this) && caller != address(c));
        // In the reference C, owner is address(this) (the deployer), so any call from
        // a non-owner must revert and leave owner unchanged.
        bool ok;
        vm.prank(caller);
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        assertTrue(!ok || c.owner() == address(this));
    }
}

