pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner, address finalOwner) public {
        // the rightful owner (whoever owner() currently is) may transfer ownership to any address
        vm.prank(c.owner());
        c.transferOwnership(newOwner);
        // the new owner may in turn transfer ownership to any other address
        vm.prank(newOwner);
        c.transferOwnership(finalOwner);
        assertTrue(c.owner() == finalOwner);
    }
}

