pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        // owner starts as address(0); attacker must be a different non-owner address
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // In the buggy version a non-owner can set the owner (require runs after the write)
        vm.prank(actor);
        try c.transferOwnership(actor) {
            // ownership change succeeded
        } catch {
            // reference version rejects it here
        }

        // General rule: owned() reverts for any caller who is not the legitimate owner.
        bool ok;
        vm.prank(actor);
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}

